const steps=[
 {number:'01',label:'Start the round',title:'One group. One shared view.',text:'A course checks in a group and records its tee time. Players and staff can then follow the same round from the first tee to the last green.',now:'In this demo, choose a sample group from the Following menu.',screen:'TEE TIME',value:'08:50',detail:'Weekend Warriors · 4 golfers',view:'journey',action:'Choose a group'},
 {number:'02',label:'Follow the fairway',title:'See the round in context.',text:'Move through each hole with the drone walkthrough. Hole details, estimated arrival times and group markers stay together in the course view.',now:'Scroll down to fly forward, scroll up to reverse, or use the hole selector. Marker positions are illustrative, not GPS.',screen:'CURRENT HOLE',value:'10 / 18',detail:'Pinehurst No. 2 · simulated position',view:'journey',action:'Explore the course'},
 {number:'03',label:'Understand the pace',title:'Know what’s ahead.',text:'Compare a group’s progress with the target time for each hole. Arrival and finish estimates use the group’s pace and traffic ahead to help staff spot delays.',now:'Open a group for its hole ETAs. Advance the demo by five minutes to see positions and estimates change.',screen:'PACE STATUS',value:'Watch pace',detail:'Hole targets + elapsed time + traffic ahead',view:'overview',action:'See the pace dashboard'},
 {number:'04',label:'Keep things moving',title:'A little attention. A better round.',text:'Course staff can review groups that need attention and record a marshal check-in. Players can see their expected finish and check out of a hole in the player view.',now:'Check-ins are saved on this device only. Real staff alerts, shared tracking and verified Monad badges are planned.',screen:'NEXT ACTION',value:'Check in',detail:'Review the group before taking action',view:'player',action:'Try the player view'}
];
export function aboutMarkup(){return `<div class="about-page"><section class="about-hero"><div><span class="about-kicker">MEET FAIRWAY FLOW</span><h2>Less waiting.<br>More good golf.</h2><p>Fairway Flow is a pace-of-play concept for golfers and the people running the course. It brings the course, group progress and round timing into one clear view.</p><div class="about-actions"><button class="primary" data-view="journey">Take the course walkthrough ↗</button><a href="#how-the-round-works">See how it works ↓</a></div></div><div class="about-course-card"><div class="about-mini-heading"><span>THE WHOLE ROUND, CONNECTED</span><span>DEMO</span></div><svg viewBox="0 0 400 230" role="img" aria-label="Illustration of connected holes and groups moving through a golf course"><path d="M30 180C90 220 60 45 150 70S190 200 250 140S290 30 370 60" fill="none" stroke="#809967" stroke-width="55" stroke-linecap="round"/><path d="M30 180C90 220 60 45 150 70S190 200 250 140S290 30 370 60" fill="none" stroke="#c1d0a2" stroke-width="2" stroke-dasharray="4 8"/><g fill="#dce5c6" stroke="#385b3d" stroke-width="2"><circle cx="75" cy="145" r="18"/><circle cx="164" cy="80" r="18"/><circle cx="255" cy="131" r="18"/></g><g fill="#35573c" font-family="sans-serif" font-size="12" text-anchor="middle"><text x="75" y="149">08</text><text x="164" y="84">09</text><text x="255" y="135">10</text></g><path d="M350 58V17l28 8-28 10" stroke="#d6e3b8" stroke-width="3" fill="#d6e3b8"/></svg><div class="about-mini-stats"><div><span>THE COURSE</span><strong>18 holes</strong></div><div><span>THE GROUPS</span><strong>One picture</strong></div><div><span>THE GOAL</span><strong>Better flow</strong></div></div></div></section><section class="about-purpose"><span class="about-kicker">WHY IT EXISTS</span><h3>A round feels better<br>when everyone knows the pace.</h3><div class="about-benefits"><article><span>01 / GOLFERS</span><h4>Enjoy the walk.</h4><p>See the hole ahead, understand your pace and get an estimated finish without losing sight of the game.</p></article><article><span>02 / COURSE TEAMS</span><h4>See the bigger picture.</h4><p>Find groups that are falling behind, spot busy holes and decide where a marshal’s attention could help.</p></article><article><span>03 / THE WHOLE COURSE</span><h4>Keep rounds connected.</h4><p>Look beyond a single slow group. Traffic ahead is part of the estimate, so staff can review the wider context.</p></article></div></section><section class="about-walkthrough" id="how-the-round-works"><div class="about-section-heading"><span class="about-kicker">FROM FIRST TEE TO FINAL PUTT</span><h3>Here’s how it works.</h3><p>Select a step to walk through the experience.</p></div><div class="about-step-buttons" aria-label="Walkthrough steps">${steps.map((s,i)=>`<button data-about-step="${i}" aria-pressed="${i===0}" aria-controls="about-step-content"><span>${s.number}</span>${s.label}</button>`).join('')}</div><div id="about-step-content" aria-live="polite">${stepMarkup(0)}</div></section><section class="about-demo-state"><div><span class="about-kicker">WHAT YOU CAN TRY TODAY</span><h3>A working concept.<br>A clear next chapter.</h3><p>This Pinehurst No. 2 experience demonstrates the idea using real course footage and simulated rounds. It is an independent demo, not an official course operations service.</p></div><div class="about-status-list"><article><span class="about-status ready">IN THE DEMO</span><h4>Explore, track and compare.</h4><p>Scroll-controlled drone footage, hole targets, arrival and finish estimates, sample group positions, filters and device-local check-ins.</p></article><article><span class="about-status planned">NEXT: CONNECT THE COURSE</span><h4>Shared data and real check-ins.</h4><p>Staff accounts, a shared tee sheet, consent-based location or QR check-ins, and calibrated ETAs need a connected backend.</p></article><article><span class="about-status planned">PLANNED: MONAD</span><h4>Recognize a well-paced round.</h4><p>Course-approved round badges could be issued through Monad after wallet and smart-contract integration. No badges or tokens are issued today.</p><button class="text-button" data-view="rewards">View the rewards concept ↗</button></article></div></section><section class="about-ending"><span class="about-kicker">TAKE IT FOR A WALK</span><h3>See the course.<br>Feel the flow.</h3><button class="primary" data-view="journey">Back to Pinehurst No. 2 ↗</button><button class="secondary" data-view="overview">Open course dashboard</button></section></div>`;}
function stepMarkup(index){const s=steps[index];return `<div class="about-step-copy"><span class="about-kicker">STEP ${s.number}</span><h4>${s.title}</h4><p>${s.text}</p><div class="about-try"><strong>TRY IT NOW</strong><p>${s.now}</p></div><button class="primary" data-view="${s.view}">${s.action} ↗</button></div><div class="about-step-preview"><span>ILLUSTRATIVE WALKTHROUGH</span><div class="about-preview-label">${s.screen}</div><strong>${s.value}</strong><p>${s.detail}</p><div class="about-preview-route"><i></i><b></b><i></i><b></b><i></i></div><small>Sample values · not a live round</small></div>`;}
export function handleAboutStep(button,root){const index=Number(button.dataset.aboutStep);if(!Number.isInteger(index)||index<0||index>=steps.length)return;root.querySelectorAll('[data-about-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.aboutStep)===index)));root.querySelector('#about-step-content').innerHTML=stepMarkup(index);}
export function aboutTeaser(){return `<section class="flight-about-section"><span class="about-kicker">THERE’S MORE TO A GOOD ROUND</span><h2>You’ve seen the course.<br>Now meet the idea.</h2><p>Discover how Fairway Flow connects group progress, hole ETAs and course operations to help the whole round move together.</p><button class="primary" data-view="about">How Fairway Flow works ↗</button><small>Independent demo · simulated tracking</small></section>`;}
